checker='"""Read-only post-import reconciliation. Never emits raw rows or credentials.\n\nServer operator sets MIGRATION_ROOT to the immutable private import directory.\nUses the existing timescaledb container and native_main_20261028 database.\nNo network requests or DB access occur when importing this module.\n"""\nimport datetime\nimport hashlib\nimport json\nimport os\nimport pathlib\nimport subprocess\nimport uuid\n\n\nclass VerificationFailure(Exception):\n    pass\n\n\ndef ensure(ok, message):\n    if not ok:\n        raise VerificationFailure(message)\n\n\ndef canonical(kind, value):\n    try:\n        return str(uuid.UUID(value))\n    except (ValueError, AttributeError):\n        return str(uuid.uuid5(uuid.NAMESPACE_OID, \'thingspanel/community/\' + kind + \'/\' + value))\n\n\ndef row_key(row, kind):\n    if kind == \'bindings\' or kind == \'origins\':\n        return row[\'tenant_id\'], row[\'device_id\']\n    if kind == \'members\':\n        return row[\'tenant_id\'], row[\'group_id\'], row[\'device_id\']\n    return row[\'id\']\n\n\ndef index(rows, kind):\n    result = {}\n    for row in rows:\n        key = row_key(row, kind)\n        ensure(key not in result, \'Duplicate \' + kind + \' identity\')\n        result[key] = row\n    return result\n\n\ndef raw_array_hashes(text, wanted):\n    """Hash the exact JSON object tokens consumed as Go json.RawMessage."""\n    decoder = json.JSONDecoder()\n    i = 0\n    def ws(pos):\n        while pos < len(text) and text[pos].isspace():\n            pos += 1\n        return pos\n    i = ws(i)\n    ensure(text[i] == \'{\', \'Invalid private input JSON\')\n    i += 1\n    while True:\n        i = ws(i)\n        if text[i] == \'}\':\n            break\n        key, end = decoder.raw_decode(text, i)\n        i = ws(end)\n        ensure(text[i] == \':\', \'Invalid private input key\')\n        start = ws(i + 1)\n        value, end = decoder.raw_decode(text, start)\n        if key == wanted:\n            if value is None:\n                return {}\n            ensure(isinstance(value, list), \'Invalid raw source collection\')\n            at = ws(start + 1)\n            result = {}\n            for _ in value:\n                row, next_at = decoder.raw_decode(text, at)\n                ensure(row[\'id\'] not in result, \'Duplicate raw source row\')\n                result[row[\'id\']] = hashlib.sha256(text[at:next_at].encode(\'utf-8\')).hexdigest()\n                at = ws(next_at)\n                if text[at] == \',\':\n                    at = ws(at + 1)\n            return result\n        i = ws(end)\n        if text[i] == \',\':\n            i += 1\n    return {}\n\n\nSQL = r"""\nBEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;\nSET LOCAL statement_timeout=\'15000ms\';\nSELECT json_build_object(\n \'database\',current_database(),\n \'schema\',(SELECT coalesce(json_agg(x),\'[]\'::json) FROM schema_migrations x),\n \'groups\',(SELECT coalesce(json_agg(x ORDER BY id),\'[]\'::json) FROM device_groups x),\n \'devices\',(SELECT coalesce(json_agg(x ORDER BY id),\'[]\'::json) FROM devices x),\n \'bindings\',(SELECT coalesce(json_agg(x ORDER BY tenant_id,device_id),\'[]\'::json) FROM device_access_bindings x),\n \'members\',(SELECT coalesce(json_agg(x ORDER BY tenant_id,group_id,device_id),\'[]\'::json) FROM device_group_members x),\n \'origins\',(SELECT coalesce(json_agg(x ORDER BY tenant_id,device_id),\'[]\'::json) FROM imported_device_origins x),\n \'gateways\',(SELECT coalesce(json_agg(x ORDER BY tenant_id,child_device_id),\'[]\'::json) FROM gateway_memberships x),\n \'receipts\',(SELECT coalesce(json_agg(x ORDER BY tenant_id,id),\'[]\'::json) FROM metadata_audit_events x WHERE operation_name=\'offline.tenant.import\')\n);\nROLLBACK;\n"""\n\n\ndef reconcile(root, current):\n    target = json.loads((root / \'target.private.json\').read_text())\n    source_hash = hashlib.sha256((root / \'source.private.json\').read_bytes()).hexdigest()\n    target_hash = hashlib.sha256((root / \'target.private.json\').read_bytes()).hexdigest()\n    resolutions_hash = hashlib.sha256((root / \'resolutions.private.json\').read_bytes()).hexdigest()\n    receipts = json.loads((root / \'applied-receipts.json\').read_text())\n    ensure(current[\'database\'] == \'native_main_20261028\', \'Wrong native database\')\n    ensure(len(current[\'schema\']) == 1 and current[\'schema\'][0][\'version\'] == 41\n           and current[\'schema\'][0][\'dirty\'] is False, \'Native schema not clean v41\')\n    actual = {k: index(current[k], k) for k in (\'groups\', \'devices\', \'bindings\', \'members\', \'origins\')}\n    baseline = {k: index(target[k], k) for k in (\'groups\', \'devices\', \'bindings\', \'members\')}\n    for kind in baseline:\n        for key, row in baseline[kind].items():\n            ensure(actual[kind].get(key) == row, \'Pre-existing native \' + kind + \' row changed\')\n    expected = {k: set(baseline[k]) for k in baseline}\n    expected_origins, results, tenant_seen = set(), [], set()\n    paths = sorted((root / \'inputs\').glob(\'*.private.json\'))\n    ensure(paths, \'No tenant inputs\')\n    for path in paths:\n        text = path.read_bytes().decode(\'utf-8\')\n        data = json.loads(text)\n        tenant = canonical(\'tenant\', data[\'source_tenant_id\'])\n        ensure(tenant not in tenant_seen, \'Duplicate tenant input\')\n        tenant_seen.add(tenant)\n        ensure(data[\'source_archive_sha256\'] == source_hash and data[\'target_archive_sha256\'] == target_hash\n               and data[\'resolutions_sha256\'] == resolutions_hash, \'Private input archive digests drifted\')\n        ensure(data[\'source_database\'] == \'ThingsPanel\' and data[\'target_database\'] == current[\'database\'], \'Input database mismatch\')\n        actor = \'migration:\' + source_hash\n        names = {r[\'source_id\']: r for r in data.get(\'name_resolutions\') or []}\n        parents = {r[\'source_id\']: r for r in data.get(\'parent_resolutions\') or []}\n        name_from_number = set(data.get(\'name_from_number\') or [])\n        quarantined = {(r[\'group_id\'], r[\'device_id\']) for r in data.get(\'excluded_members\') or []}\n        excluded_gateways = {(r[\'device_id\'], r[\'target_id\']) for r in data.get(\'excluded_gateways\') or []}\n        groups, devices, templates = data[\'groups\'], data.get(\'devices\') or [], data.get(\'templates\') or []\n        device_map = {r[\'id\']: r for r in devices}\n        ensure(all(d in device_map and device_map[d].get(\'parent_id\') == p for d, p in excluded_gateways), \'Excluded gateway source pair differs\')\n        template_map = {r[\'id\']: r for r in templates}\n        device_hashes = raw_array_hashes(text, \'devices\')\n        template_hashes = raw_array_hashes(text, \'templates\')\n        for row in groups:\n            gid = row[\'id\']\n            ensure(row[\'tenant_id\'] == data[\'source_tenant_id\'], \'Foreign source group\')\n            name = names[gid][\'name\'] if gid in names else row[\'name\']\n            parent = row.get(\'parent_id\') or None\n            if parent == \'0\':\n                parent = None\n            if gid in parents:\n                ensure(parents[gid][\'original_parent_id\'] == row.get(\'parent_id\'), \'Parent approval drift\')\n                parent = None\n            found = actual[\'groups\'].get(gid)\n            ensure(found is not None and found[\'tenant_id\'] == tenant and found[\'name\'] == name\n                   and found[\'parent_id\'] == parent and found[\'created_by\'] == actor\n                   and found[\'deleted_at\'] is None, \'Imported group metadata differs from approved source\')\n            expected[\'groups\'].add(gid)\n        for row in devices:\n            did = row[\'id\']\n            ensure(row[\'tenant_id\'] == data[\'source_tenant_id\'], \'Foreign source device\')\n            found = actual[\'devices\'].get(did)\n            wanted_name = row[\'device_number\'] if did in name_from_number else row[\'name\']\n            ensure(found is not None and found[\'tenant_id\'] == tenant and found[\'name\'] == wanted_name\n                   and found[\'device_number\'] == row[\'device_number\'] and found[\'created_by\'] == actor\n                   and found[\'administrative_state\'] == (\'enabled\' if row.get(\'is_enabled\') == \'enabled\' else \'disabled\')\n                   and found[\'activation_state\'] == row[\'activate_flag\'] and found[\'deleted_at\'] is None,\n                   \'Imported device identity/lifecycle differs from source\')\n            b = actual[\'bindings\'].get((tenant, did))\n            ensure(b is not None and b[\'template_id\'] is None and b[\'direct_access\'] is None\n                   and b[\'device_parameters\'] == {} and \'model_id\' not in b and \'model_snapshot_id\' not in b\n                   and b[\'configuration_generation\'] == 1 and b[\'pending_operation_id\'] is None\n                   and b[\'runtime_provider_id\'] == \'760c2298-8b97-51f1-bd71-2737d6278f21\'\n                   and b[\'runtime_namespace\'] == \'community\' and b[\'runtime_external_id\'] == did\n                   and b[\'service_instance_id\'] == (row.get(\'service_access_id\') or None), \'Imported binding fabricated or incomplete\')\n            template_id = row.get(\'device_config_id\') or None\n            template = template_map.get(template_id, {})\n            o = actual[\'origins\'].get((tenant, did))\n            ensure(o is not None, \'Imported origin missing\')\n            origin_fields = {\'source_owner\': \'community\', \'source_database\': data[\'source_database\'],\n                             \'source_deployment_id\': data[\'source_deployment_id\'], \'source_tenant_id\': data[\'source_tenant_id\'],\n                             \'source_device_id\': did, \'source_template_id\': template_id,\n                             \'source_template_name\': template.get(\'name\') or None,\n                             \'source_protocol\': row.get(\'protocol\') or template.get(\'protocol_type\') or None,\n                             \'source_access_way\': row.get(\'access_way\') or None,\n                             \'source_service_access_id\': row.get(\'service_access_id\') or None,\n                             \'source_row_sha256\': device_hashes[did],\n                             \'source_template_sha256\': template_hashes.get(template_id),\n                             \'source_archive_sha256\': source_hash, \'imported_by\': actor}\n            ensure(all(o.get(k) == v for k, v in origin_fields.items()), \'Imported source provenance differs\')\n            links = [x for x in current[\'gateways\'] if x[\'tenant_id\'] == tenant and x[\'child_device_id\'] == did]\n            if (did, row.get(\'parent_id\')) in excluded_gateways:\n                ensure(not links, \'Quarantined gateway edge inserted\')\n            elif row.get(\'parent_id\'):\n                ensure(len(links) == 1 and links[0][\'gateway_device_id\'] == row[\'parent_id\']\n                       and links[0][\'subdevice_address\'] == row[\'sub_device_addr\'], \'Imported gateway relation differs\')\n            else:\n                ensure(not links, \'Unexpected imported gateway edge\')\n            expected[\'devices\'].add(did)\n            expected[\'bindings\'].add((tenant, did))\n            expected_origins.add((tenant, did))\n        edges = set()\n        for m in data.get(\'members\') or []:\n            if (m[\'group_id\'], m[\'device_id\']) in quarantined:\n                ensure((tenant, m[\'group_id\'], m[\'device_id\']) not in actual[\'members\'], \'Quarantined cross-tenant edge inserted\')\n                continue\n            edge = (tenant, m[\'group_id\'], m[\'device_id\'])\n            ensure(edge in actual[\'members\'] and actual[\'members\'][edge][\'created_by\'] == actor, \'Imported membership missing\')\n            edges.add(edge)\n            expected[\'members\'].add(edge)\n        saved = [r for r in receipts if r[\'tenant_id\'] == tenant]\n        stored = [r for r in current[\'receipts\'] if r[\'tenant_id\'] == tenant\n                  and r[\'redacted_changes\'].get(\'source_archive_sha256\') == source_hash]\n        ensure(len(saved) == len(stored) == 1, \'Tenant committed receipt missing/ambiguous\')\n        ensure(stored[0][\'outcome\'] == \'succeeded\' and stored[0][\'redacted_changes\'][\'input_sha256\'] == saved[0][\'input_sha256\'], \'Committed receipt digest mismatch\')\n        for key, value in [(\'groups\', len(groups)), (\'devices\', len(devices)), (\'members\', len(edges)), (\'source_templates\', len(templates)), (\'quarantined_gateways\', len(excluded_gateways))]:\n            ensure(stored[0][\'redacted_changes\'][key] == value, \'Committed receipt count mismatch\')\n        results.append({\'tenant_id\': tenant, \'groups\': len(groups), \'devices\': len(devices),\n                        \'source_templates\': len(templates), \'members\': len(edges), \'quarantined_members\': len(quarantined), \'quarantined_gateways\': len(excluded_gateways),\n                        \'distinct_member_devices\': len({x[2] for x in edges}), \'status\': \'PASS\'})\n    for kind, keys in expected.items():\n        ensure(set(actual[kind]) == keys, \'Unexpected/missing native \' + kind + \' identity set\')\n    ensure(set(actual[\'origins\']) == expected_origins, \'Origin identity set differs from imported closure\')\n    return {\'status\': \'PASS\', \'read_only\': True, \'database\': current[\'database\'], \'tenant_results\': results,\n            \'pre_existing_rows_unchanged\': {k: len(v) for k, v in baseline.items()},\n            \'native_totals\': {k: len(v) for k, v in actual.items()}, \'source_archive_sha256\': source_hash}\n\n\ndef main():\n    os.umask(0o077)\n    root = pathlib.Path(os.environ[\'MIGRATION_ROOT\']).resolve()\n    allowed = pathlib.Path(\'/opt/tp-community-actions/group-migration\').resolve()\n    ensure(root != allowed and allowed in root.parents, \'Unexpected migration directory\')\n    p = subprocess.run([\'docker\', \'exec\', \'-i\', \'timescaledb\', \'psql\', \'-X\', \'-q\', \'-At\',\n                        \'-v\', \'ON_ERROR_STOP=1\', \'-U\', \'postgres\', \'-d\', \'native_main_20261028\'],\n                       input=SQL.encode(), stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=45)\n    ensure(p.returncode == 0, \'Read-only native reconciliation query failed\')\n    try:\n        current = json.loads(p.stdout)\n    except ValueError:\n        raise VerificationFailure(\'Invalid native reconciliation query result\')\n    result = reconcile(root, current)\n    result[\'checked_at\'] = datetime.datetime.now(datetime.timezone.utc).isoformat()\n    (root / \'formal-import-db-verification.json\').write_text(json.dumps(result, indent=2))\n    print(json.dumps(result))\n\n\nif __name__ == \'__main__\':\n    try:\n        main()\n    except VerificationFailure as e:\n        print(json.dumps({\'status\': \'FAIL\', \'read_only\': True, \'error\': str(e)}))\n        raise SystemExit(1)\n    except Exception as e:\n        print(json.dumps({\'status\': \'FAIL\', \'read_only\': True, \'error\': \'checker exception: \' + type(e).__name__}))\n        raise SystemExit(1)\n'
source_query="BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;\nWITH RECURSIVE ids(id) AS (\n SELECT DISTINCT device_id FROM r_group_device WHERE group_id IN (SELECT id FROM groups)\n UNION\n SELECT d.parent_id FROM devices d JOIN ids ON ids.id=d.id WHERE d.parent_id IS NOT NULL AND d.parent_id<>'' AND d.parent_id<>'0'\n)\nSELECT json_build_object('source_database','ThingsPanel','recorded_at',transaction_timestamp(),\n 'groups',(SELECT coalesce(json_agg(t),'[]'::json) FROM (SELECT * FROM groups ORDER BY id)t),\n 'members',(SELECT coalesce(json_agg(t),'[]'::json) FROM (SELECT r.*,g.tenant_id FROM r_group_device r JOIN groups g ON g.id=r.group_id ORDER BY r.group_id,r.device_id)t),\n 'devices',(SELECT coalesce(json_agg(t),'[]'::json) FROM (SELECT * FROM devices WHERE id IN(SELECT id FROM ids) ORDER BY id)t),\n 'templates',(SELECT coalesce(json_agg(t),'[]'::json) FROM (SELECT * FROM device_configs WHERE id IN (SELECT device_config_id FROM devices WHERE id IN(SELECT id FROM ids)) ORDER BY id)t));ROLLBACK;"
scope={'__name__':'readonly_verifier'}
exec(compile(checker,'verification','exec'),scope)
with contextlib.redirect_stdout(io.StringIO()):scope['main']()
p=subprocess.run(['docker','exec','-i','timescaledb','psql','-X','-q','-At','-v','ON_ERROR_STOP=1','-U','postgres','-d','ThingsPanel'],input=source_query.encode(),stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=60)
assert p.returncode==0
